getUserIdWithEmail(email) {
  email = email.toLowerCase();
  for (const u of this.userIds) {
    let e;
    try {
      e = lazy.EnigmailFuncs.stripEmail(u.userId.toLowerCase());
    } catch (x) {
      e = u.userId.toLowerCase();
    }

    if (email == e) {
      return u;
    }
  }

  return null;
}
